// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"IB Chemistry starts with particles: atoms, ions and molecules, and how we count them.","blocks":[{"t":"key","text":"The mole: n = m/M and N = nNₐ (Nₐ = 6.02 × 10²³). Empirical formulas come from mass percentages; molecular formulas are multiples of the empirical formula. Concentration c = n/V."},{"t":"p","text":"Atomic structure: protons and neutrons in the nucleus, electrons in energy levels. Isotopes differ in neutron number; relative atomic mass is a weighted average, measured with a mass spectrometer."},{"t":"p","text":"Ideal gas law: pV = nRT; at STP (273 K, 100 kPa), molar volume is 22.7 dm³ mol⁻¹."},{"t":"ex","problem":"How many moles are in 11 g of CO₂ (M = 44 g mol⁻¹)?","steps":["n = m/M = 11/44"],"answer":"0.25 mol"}]},{"say":"Where electrons are located determines how atoms behave. Spectra let us see their energy levels.","blocks":[{"t":"key","text":"Electrons fill orbitals in order of increasing energy (Aufbau principle): 1s 2s 2p 3s 3p 4s 3d 4p. Pauli exclusion: two electrons per orbital with opposite spins. Hund's rule: fill degenerate orbitals singly first. Exceptions: Cr ([Ar] 3d⁵ 4s¹) and Cu ([Ar] 3d¹⁰ 4s¹)."},{"t":"p","text":"The hydrogen emission spectrum is a line spectrum: electrons drop between energy levels, emitting photons of specific frequencies. Lines converge at higher frequency; the convergence limit corresponds to ionization."},{"t":"p","text":"HL: successive ionization energies reveal the group; first ionization energies show patterns across periods."},{"t":"ex","problem":"Write the configuration of iron (Z = 26).","steps":["1s² 2s² 2p⁶ 3s² 3p⁶ then 4s² 3d⁶"],"answer":"[Ar] 3d⁶ 4s²"}]}],[{"say":"Bonding explains why substances have the properties they do: from salt crystals to DNA.","blocks":[{"t":"key","text":"Ionic bonding: electrostatic attraction between oppositely charged ions in a lattice; high melting points, conduct when molten or dissolved."},{"t":"p","text":"Covalent bonding: shared electron pairs. VSEPR predicts shapes (linear, trigonal planar, tetrahedral, bent, trigonal pyramidal). Polarity depends on electronegativity differences and molecular shape."},{"t":"p","text":"Metallic bonding: cations in a sea of delocalized electrons; conductivity and malleability."},{"t":"p","text":"Intermolecular forces (weakest to strongest): London dispersion, dipole-induced dipole, dipole–dipole, hydrogen bonding. Stronger forces → higher boiling points."},{"t":"p","text":"The bonding triangle (van Arkel–Ketelaar) classifies substances by electronegativity difference and average electronegativity."}]},{"say":"The periodic table organizes elements by structure, and organic chemistry names carbon compounds systematically.","blocks":[{"t":"key","text":"Periodic trends: atomic radius decreases across a period and increases down a group; ionization energy and electronegativity increase across a period and decrease down a group. Explanations use nuclear charge and shielding."},{"t":"p","text":"Oxides: metal oxides are basic; non-metal oxides are acidic (causing acid rain)."},{"t":"p","text":"Organic chemistry: homologous series (alkanes, alkenes, alcohols, carboxylic acids…) share a functional group and general formula. IUPAC names use the longest chain (meth-, eth-, prop-, but-…) and suffixes (-ane, -ene, -ol, -oic acid). Isomers have the same molecular formula but different structures."},{"t":"ex","problem":"Name CH₃CH₂CH₂OH.","steps":["Three carbons: prop-; alcohol: -ol on carbon 1"],"answer":"propan-1-ol"}]}],[{"say":"Reactivity 1 asks why reactions happen. Energy changes are the first part of the answer.","blocks":[{"t":"key","text":"Exothermic reactions release heat (ΔH < 0); endothermic reactions absorb heat (ΔH > 0). Calorimetry: Q = mcΔT, then ΔH = −Q/n."},{"t":"p","text":"Bond enthalpies: ΔH = Σ(bonds broken) − Σ(bonds formed). Hess's law: ΔH for a reaction is the same regardless of route. Using enthalpies of formation: ΔH = ΣΔHf(products) − ΣΔHf(reactants)."},{"t":"p","text":"Combustion of fuels releases energy; incomplete combustion produces carbon monoxide and soot."},{"t":"p","text":"HL: Born–Haber cycles, entropy (ΔS) and Gibbs energy ΔG = ΔH − TΔS (spontaneous if ΔG < 0)."},{"t":"ex","problem":"Breaking bonds requires 1,200 kJ and forming bonds releases 1,500 kJ. Find ΔH.","steps":["ΔH = 1,200 − 1,500"],"answer":"−300 kJ (exothermic)"}]},{"say":"How fast reactions happen depends on collisions. Catalysts can speed them up dramatically.","blocks":[{"t":"key","text":"Collision theory: reactions occur when particles collide with energy ≥ Eₐ and the correct orientation. Rate increases with concentration, pressure, surface area, temperature and catalysts."},{"t":"p","text":"Maxwell–Boltzmann distributions show that raising temperature increases the fraction of particles with E ≥ Eₐ. Catalysts lower Eₐ by providing an alternative pathway."},{"t":"p","text":"HL: rate equations (rate = k[A]ᵐ[B]ⁿ), orders from experimental data, mechanisms with a rate-determining step, and the Arrhenius equation k = Ae^(−Eₐ/RT)."},{"t":"ex","problem":"Doubling [A] doubles the rate. What is the order with respect to A?","steps":["2ᵐ = 2"],"answer":"First order"}]}],[{"say":"How much product can we make, and when does a reaction stop? Stoichiometry and equilibrium answer these.","blocks":[{"t":"key","text":"Stoichiometry uses mole ratios from balanced equations. The limiting reactant determines theoretical yield. Percentage yield = actual/theoretical × 100%. Atom economy = mass of desired product/total mass of reactants × 100%."},{"t":"p","text":"Dynamic equilibrium: forward and reverse rates are equal. The equilibrium constant K = [products]/[reactants] (raised to coefficients). Le Chatelier's principle predicts shifts when concentration, pressure or temperature change. Only temperature changes K."},{"t":"ex","problem":"For N₂ + 3H₂ ⇌ 2NH₃ (exothermic), how does raising temperature affect yield?","steps":["Raising temperature favors the endothermic (reverse) direction"],"answer":"Yield of NH₃ decreases (and K decreases)"}]},{"say":"Proton transfer and electron transfer are two of the most important types of reactions.","blocks":[{"t":"key","text":"Brønsted–Lowry acids donate protons; bases accept them. Conjugate pairs differ by one H⁺. pH = −log[H⁺]; at 298 K, Kw = 1.0 × 10⁻¹⁴ and pH + pOH = 14. Strong acids fully dissociate; weak acids partially dissociate."},{"t":"p","text":"Neutralization produces a salt and water. Titrations find unknown concentrations; buffers resist pH changes."},{"t":"p","text":"Redox: oxidation is loss of electrons (increase in oxidation state), reduction is gain (decrease). In voltaic cells, chemical energy becomes electrical energy; oxidation occurs at the anode. Electrolytic cells use electricity to drive non-spontaneous reactions."},{"t":"p","text":"Organic mechanisms (Reactivity 3): nucleophilic substitution, electrophilic addition to alkenes, and (HL) more mechanisms with curly arrows."}]}]];
export default text;
